{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service Version 1 is not disabled",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not explicitly disable IMDSv1, leaving it vulnerable to Server-Side Request Forgery (SSRF) attacks where credentials can be stolen via the metadata endpoint."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "EBS volumes are not encrypted",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The root EBS volume attached to the instance is not encrypted at rest, exposing data to unauthorized access if the underlying storage is compromised."
    },
    {
      "check_id": "CKV_AWS_126",
      "title": "Detailed monitoring is not enabled",
      "resource": "aws_instance.web",
      "severity": "LOW",
      "explanation": "Detailed monitoring is disabled, which limits visibility into instance performance and security anomalies, hindering incident response."
    },
    {
      "check_id": "CKV_AWS_135",
      "title": "Instance is not EBS optimized",
      "resource": "aws_instance.web",
      "severity": "LOW",
      "explanation": "The instance is not EBS optimized, which can lead to inconsistent I/O performance and potential bottlenecks for EBS-backed workloads."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t2.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n\n  monitoring             = true\n  ebs_optimized          = true\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Enabled detailed monitoring and EBS optimization. Configured metadata options to require IMDSv2 (http_tokens = \"required\") to mitigate SSRF risks. Enabled encryption for the root block device to secure data at rest."
}
